import assert from "node:assert/strict";
import {execFileSync} from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import {fileURLToPath} from "node:url";

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),".."),source=path.join(root,"tests","fixtures","scaffold-plugin");

test("Library scaffold generation discovers the registered Rack module contract",()=>{
  const output=fs.mkdtempSync(path.join(os.tmpdir(),"rack-web-scaffold-test-"));
  const stdout=execFileSync(process.execPath,[path.join(root,"scripts","scaffold-library-module.mjs"),"https://library.vcvrack.com/FixturePlugin/Simple","--manifest-file",path.join(source,"plugin.json"),"--source-dir",source,"--output",output],{encoding:"utf8"});
  const report=JSON.parse(stdout),saved=JSON.parse(fs.readFileSync(path.join(output,"adapter.json"),"utf8"));
  assert.equal(report.key,"FixturePlugin/Simple");assert.equal(saved.source.file,"src/Simple.hpp");assert.equal(saved.source.registrationFile,"src/Simple.cpp");assert.equal(saved.source.moduleClass,"FixtureModule");assert.deepEqual(saved.detected.enums.inputs.identifiers,["SIGNAL_INPUT","NUM_INPUTS"]);assert.deepEqual(saved.detected.config.bypass,["SIGNAL_INPUT, SIGNAL_OUTPUT"]);assert.equal(saved.assessment.strategy,"direct-rack-source-adapter");assert.equal(saved.assessment.compileEligible,true);assert.match(fs.readFileSync(path.join(output,"adapter.cpp"),"utf8"),/RACK_WEB_EXPORTS\(FixtureModule\)/);const runtime=JSON.parse(fs.readFileSync(path.join(output,"runtime.json"),"utf8"));assert.deepEqual(runtime.params,[{id:0,name:"Level",min:0,max:1,default:1,position:{x:29.528,y:59.055,centered:true,widget:"RoundBlackKnob"}}]);assert.deepEqual(runtime.inputs[0].position,{x:12,y:300});assert.deepEqual(runtime.outputs[0].position,{x:150,y:330,centered:true});assert.deepEqual(runtime.bypassRoutes,[[0,0]]);
  fs.rmSync(output,{recursive:true,force:true});
});

test("plugin.hpp DSP helpers are collected transitively without importing UI helpers",()=>{
  const temporary=fs.mkdtempSync(path.join(os.tmpdir(),"rack-web-plugin-helper-test-")),plugin=path.join(temporary,"plugin"),output=path.join(temporary,"output");fs.cpSync(source,plugin,{recursive:true});
  fs.writeFileSync(path.join(plugin,"src","PluginConstants.hpp"),'#pragma once\nconst float fixturePluginScale = 3.f;\n');
  fs.writeFileSync(path.join(plugin,"src","plugin.hpp"),'#pragma once\n#include <rack.hpp>\n#include "PluginConstants.hpp"\nusing namespace rack;\nusing namespace std;\nenum class FixturePluginMode { Off, On };\nstruct FixturePluginMessage { float value = 0.f; };\nstruct FixturePluginQuantity : ParamQuantity { float getDisplayValue() override; };\nconst int fixtureUpdateRate = 2;\nfloat fixtureOutOfLine(float value);\ninline float fixtureHelperLeaf(float value) { return value * 2.f; }\ninline float fixtureHelperBridge(float value) { return fixtureOutOfLine(fixtureHelperLeaf(value)) + 1.f; }\ninline NVGcolor fixtureUiColor() { return nvgRGB(255, 0, 0); }\n');
  fs.writeFileSync(path.join(plugin,"src","plugin.cpp"),'#include "plugin.hpp"\nfloat FixturePluginQuantity::getDisplayValue() { return fixtureOutOfLine(getValue()); }\nfloat fixtureOutOfLine(float value) { return value * fixturePluginScale + MOOG_PI - MOOG_PI; }\n');
  const header=path.join(plugin,"src","Simple.hpp"),simple=fs.readFileSync(header,"utf8").replace("struct FixtureModule : Module {","struct FixtureModule : Module {\n  FixturePluginMode pluginMode = FixturePluginMode::On;\n  unique_ptr<float> pluginValue = make_unique<float>(2.f);\n  float orderedScale = fixturePluginScale;").replace("configParam(LEVEL_PARAM","configParam<FixturePluginQuantity>(LEVEL_PARAM").replace("inputs[SIGNAL_INPUT].getVoltage() * params[LEVEL_PARAM].getValue()","FixturePluginMessage{fixtureHelperBridge(inputs[SIGNAL_INPUT].getVoltage() * params[LEVEL_PARAM].getValue()) * fixtureUpdateRate + *pluginValue + orderedScale - fixturePluginScale}.value");fs.writeFileSync(header,simple);
  try{execFileSync(process.execPath,[path.join(root,"scripts","scaffold-library-module.mjs"),"https://library.vcvrack.com/FixturePlugin/Simple","--manifest-file",path.join(plugin,"plugin.json"),"--source-dir",plugin,"--output",output,"--compile"],{encoding:"utf8"});const adapter=fs.readFileSync(path.join(output,"adapter.cpp"),"utf8"),constantIndex=adapter.indexOf("fixturePluginScale = 3.f"),implementationIndex=adapter.indexOf("float fixtureOutOfLine(float value) {");assert.match(adapter,/using namespace std/);assert.match(adapter,/enum class FixturePluginMode/);assert.match(adapter,/struct FixturePluginMessage/);assert.match(adapter,/FixturePluginQuantity::getDisplayValue/);assert.match(adapter,/const int fixtureUpdateRate = 2;/);assert.ok(constantIndex>=0&&implementationIndex>constantIndex);assert.match(adapter,/inline constexpr double MOOG_PI/);assert.match(adapter,/float fixtureHelperBridge\(float value\)/);assert.match(adapter,/float fixtureHelperLeaf\(float value\)/);assert.doesNotMatch(adapter,/fixtureUiColor/);const wasm=new WebAssembly.Instance(new WebAssembly.Module(fs.readFileSync(path.join(output,"module.wasm"))),{}).exports;wasm._initialize();wasm.rack_web_set_input_connected(0,1);wasm.rack_web_set_input_channels(0,1);new Float32Array(wasm.memory.buffer,wasm.rack_web_input_buffer(),128)[0]=2;wasm.rack_web_process(1,48000);assert.equal(new Float32Array(wasm.memory.buffer,wasm.rack_web_output_buffer(),128)[0],28)}finally{fs.rmSync(temporary,{recursive:true,force:true})}
});

